window.SNP_STAGING_DOCS = [{"code": "CO-01", "cat": "company", "order": 0, "title": "Articles of Organization", "why": "Proof the LLC exists, filed with the Arizona Corporation Commission. Banks, suppliers and other states ask for it when you open accounts or register.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "One-time", "notes": "", "template": "", "files": []}, {"code": "CO-02", "cat": "company", "order": 1, "title": "Operating Agreement", "why": "The rulebook between the two 50/50 members: voting, what happens on a deadlock, how profit is distributed, and the buyout process if a member leaves. It should also say that memberships, tax IDs and the domain belong to the LLC.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "Attorney", "renews": "Update when ownership or terms change", "notes": "", "template": "", "files": []}, {"code": "CO-03", "cat": "company", "order": 2, "title": "IRS EIN confirmation letter (CP 575 or 147C)", "why": "The IRS letter that confirms SNP's federal tax ID. Banks, the purchasing program and state tax agencies ask for it.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "One-time", "notes": "", "template": "", "files": []}, {"code": "CO-04", "cat": "company", "order": 3, "title": "Membership ledger & member consents", "why": "A record of who owns what percentage, plus signed written consents for big decisions (opening bank accounts, adding a division, signing large contracts).", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Update as decisions are made", "notes": "", "template": "", "files": []}, {"code": "CO-05", "cat": "company", "order": 4, "title": "Statutory agent appointment", "why": "Arizona requires a statutory agent on file to receive legal papers. Keep the agent's name, address and the signed acceptance.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Update if the agent changes", "notes": "", "template": "", "files": []}, {"code": "CO-06", "cat": "company", "order": 5, "title": "Certificate of Good Standing", "why": "Short certificate from the Arizona Corporation Commission showing the LLC is active. Lenders and some suppliers request a recent one.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Order fresh when requested", "notes": "", "template": "", "files": []}, {"code": "CO-07", "cat": "company", "order": 6, "title": "Trade name registration", "why": "If the company operates under a name other than its exact legal name (for example a division name), register it as a trade name with the Arizona Secretary of State.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Arizona trade names renew every 5 years", "notes": "", "template": "", "files": []}, {"code": "CO-08", "cat": "company", "order": 7, "title": "Beneficial ownership (BOI) report", "why": "FinCEN's final rule exempts companies formed in the US from BOI reporting, so SNP does not need to file. Kept here as a record of that decision.", "priority": "As needed", "division": "All divisions", "status": "Not needed", "assignee": "", "renews": "Recheck if the rules change", "notes": "", "template": "", "files": []}, {"code": "TX-01", "cat": "tax", "order": 0, "title": "Arizona TPT license", "why": "Arizona's sales tax (transaction privilege tax) license. Needed to make wholesale sales in Arizona and to give suppliers an Arizona resale certificate.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Renews annually (Jan 1)", "notes": "", "template": "", "files": []}, {"code": "TX-02", "cat": "tax", "order": 1, "title": "Sales tax permits & resale IDs by state", "why": "One entry per state: permit number, filing frequency, renewal date and login owner.", "priority": "Critical", "division": "All divisions", "status": "In progress", "assignee": "Accountant", "renews": "Varies by state", "notes": "", "template": "", "files": []}, {"code": "TX-03", "cat": "tax", "order": 2, "title": "Customer resale / exemption certificates", "why": "When SNP sells without charging sales tax, it must hold each customer's valid resale certificate. Without it, the state can bill SNP for the tax it didn't collect.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Check expiry dates yearly", "notes": "", "template": "", "files": []}, {"code": "TX-04", "cat": "tax", "order": 3, "title": "SNP's resale certificates to suppliers", "why": "The certificates SNP gives its own suppliers (Arizona Form 5000A, the multistate MTC form, or each state's form) so purchases for resale aren't taxed.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Re-issue when a supplier asks", "notes": "", "template": "", "files": []}, {"code": "TX-05", "cat": "tax", "order": 4, "title": "Form W-9 (SNP's own, signed)", "why": "Customers, the purchasing program and payment platforms ask for SNP's W-9 before paying or onboarding.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Re-sign if address or tax ID changes", "notes": "", "template": "", "files": []}, {"code": "TX-06", "cat": "tax", "order": 5, "title": "W-9s from payees & 1099 filings", "why": "Collect a W-9 from anyone SNP pays (referral partners, contractors) so the 1099-NEC forms can be filed by January 31.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "1099s due Jan 31 each year", "notes": "", "template": "", "files": []}, {"code": "TX-07", "cat": "tax", "order": 6, "title": "Partnership return (Form 1065) & K-1s", "why": "A two-member LLC files a partnership return each year unless it elected otherwise; each owner gets a K-1.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Due Mar 15 each year", "notes": "", "template": "", "files": []}, {"code": "TX-08", "cat": "tax", "order": 7, "title": "Sales tax filing calendar & returns", "why": "Due dates for every state's sales tax return, with copies of filed returns and payment confirmations.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Monthly / quarterly / annual by state", "notes": "", "template": "", "files": []}, {"code": "TX-09", "cat": "tax", "order": 8, "title": "City business licenses", "why": "Some Arizona cities and other states' cities require a local business or privilege license. Check where SNP has an office or warehouse.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Usually annual", "notes": "", "template": "", "files": []}, {"code": "TX-10", "cat": "tax", "order": 9, "title": "Pesticide dealer licenses (pool chemicals)", "why": "Pool sanitizers such as chlorine are EPA-registered pesticides. Some states require distributors to hold a dealer license before selling them; check each state SNP ships to.", "priority": "As needed", "division": "Commercial supply", "status": "Not checked", "assignee": "", "renews": "Usually annual", "notes": "", "template": "", "files": []}, {"code": "SA-01", "cat": "sales", "order": 0, "title": "Sourcing & Purchasing Services Agreement", "why": "The oil brokerage contract. Spells out SNP's role when the customer pays the supplier directly: SNP arranges the order, never takes title, keeps any program rewards, and is protected from being cut out.", "priority": "Critical", "division": "Oil", "status": "Not checked", "assignee": "Attorney", "renews": "Review yearly", "notes": "", "template": "t1", "files": []}, {"code": "SA-02", "cat": "sales", "order": 1, "title": "Wholesale Terms & Conditions of Sale", "why": "The sales agreement for orders where SNP buys and resells (phones, electronics, commercial supply): pricing, payment, delivery, title, returns and warranty limits.", "priority": "Critical", "division": "Phones & electronics, Commercial supply", "status": "Not checked", "assignee": "Attorney", "renews": "Review yearly", "notes": "", "template": "t2", "files": []}, {"code": "SA-03", "cat": "sales", "order": 2, "title": "Customer account & credit application", "why": "Collects each customer's legal name, tax ID, resale certificate, references and signature before the first order. Includes an optional personal guaranty for credit terms.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Refresh every 2 years", "notes": "", "template": "t5", "files": []}, {"code": "SA-04", "cat": "sales", "order": 3, "title": "Quote / pro forma invoice template", "why": "A standard quote with validity date, condition grade, shipping terms and a line saying the Terms of Sale apply. LATAM buyers often need a pro forma to send payment.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "", "notes": "", "template": "", "files": []}, {"code": "SA-05", "cat": "sales", "order": 4, "title": "Sales invoice template", "why": "Standard invoice showing PO number, tax treatment (taxable or resale-exempt), payment terms and remit-to details.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "", "notes": "", "template": "", "files": []}, {"code": "SA-06", "cat": "sales", "order": 5, "title": "Returns & RMA policy", "why": "How customers request a return, what qualifies, time limits and restocking fees. Mostly matters for phones and electronics.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Review yearly", "notes": "", "template": "", "files": []}, {"code": "SA-07", "cat": "sales", "order": 6, "title": "Product condition & grading definitions", "why": "Plain definitions of New, Open box and Grade A/B/C refurbished, so every quote and dispute refers to the same standard.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "", "notes": "", "template": "", "files": []}, {"code": "SA-08", "cat": "sales", "order": 7, "title": "Customer dispute & complaint log", "why": "A running record of complaints, shortages and how each was resolved. Useful evidence if a customer disputes a payment.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Ongoing", "notes": "", "template": "", "files": []}, {"code": "SU-01", "cat": "supply", "order": 0, "title": "Purchasing program membership & rewards terms", "why": "A saved copy of each membership agreement and rewards program's rules. Have counsel confirm the way SNP uses them fits those rules.", "priority": "Critical", "division": "Oil", "status": "Not checked", "assignee": "Attorney", "renews": "Recheck whenever the program updates its terms", "notes": "", "template": "", "files": []}, {"code": "SU-02", "cat": "supply", "order": 1, "title": "Membership register", "why": "Which membership is in whose name, authorized card holders, renewal dates and the state tax ID linked to each. Never record full card numbers here.", "priority": "Critical", "division": "Oil", "status": "Not checked", "assignee": "", "renews": "Update on each renewal", "notes": "", "template": "", "files": []}, {"code": "SU-03", "cat": "supply", "order": 2, "title": "Rewards reconciliation log", "why": "Each order matched to the reward earned, the date it was deposited and how it was split. This is the backup for the profit-share statements.", "priority": "Important", "division": "Oil", "status": "Not checked", "assignee": "Accountant", "renews": "Monthly", "notes": "", "template": "", "files": []}, {"code": "SU-04", "cat": "supply", "order": 3, "title": "Purchase order template", "why": "The PO SNP sends suppliers for the resale divisions: items, condition grade, price, ship-to, and SNP's purchase terms.", "priority": "Important", "division": "Phones & electronics, Commercial supply", "status": "Not checked", "assignee": "", "renews": "", "notes": "", "template": "t6", "files": []}, {"code": "SU-05", "cat": "supply", "order": 4, "title": "Supplier onboarding pack", "why": "For each new supplier: W-9, certificate of insurance, two trade references, bank verification letter and a signed NDA.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Refresh every 2 years", "notes": "", "template": "", "files": []}, {"code": "SU-06", "cat": "supply", "order": 5, "title": "Supplier / distribution agreements", "why": "Signed supply terms with each main supplier: pricing, minimums, lead times, warranty pass-through and returns.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Per contract term", "notes": "", "template": "", "files": []}, {"code": "PA-01", "cat": "partners", "order": 0, "title": "Referral & profit-share agreement", "why": "Puts any profit-share arrangement in writing: what counts as net revenue, when payment is due, monthly statements, audit rights, non-circumvention and what happens if it ends.", "priority": "Critical", "division": "Oil", "status": "Not checked", "assignee": "Attorney", "renews": "Review yearly", "notes": "", "template": "t4", "files": []}, {"code": "PA-02", "cat": "partners", "order": 1, "title": "Mutual NDA & non-circumvention agreement", "why": "Sign before sharing supplier names, pricing or customer lists with anyone. Brokers rely on the non-circumvention clause to keep from being cut out of a deal.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Per counterparty", "notes": "", "template": "t3", "files": []}, {"code": "PA-03", "cat": "partners", "order": 2, "title": "Accounting engagement letter", "why": "A short letter setting out the monthly fee and what's included: bookkeeping, sales tax filings, the 1065 and K-1s.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Review yearly", "notes": "", "template": "", "files": []}, {"code": "PA-04", "cat": "partners", "order": 3, "title": "Contractor & sales rep agreements", "why": "For the web team, sales reps and anyone paid per deal: scope, commission, confidentiality, and that work product belongs to SNP.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Per contractor", "notes": "", "template": "", "files": []}, {"code": "PR-01", "cat": "product", "order": 0, "title": "Safety Data Sheets (SDS) for every product", "why": "Manufacturer SDS for each motor oil and pool chemical SNP sells. Customers, carriers and inspectors ask for them.", "priority": "Critical", "division": "Oil, Commercial supply", "status": "Not checked", "assignee": "", "renews": "Update when the manufacturer revises", "notes": "", "template": "", "files": []}, {"code": "PR-02", "cat": "product", "order": 1, "title": "Hazmat shipping papers & training records", "why": "Some pool chemicals (calcium hypochlorite, for example) ship as regulated hazardous materials, and phones contain lithium batteries. Whoever prepares those shipments needs DOT hazmat training; confirm whether that's SNP or the supplier.", "priority": "Important", "division": "Phones & electronics, Commercial supply", "status": "Not checked", "assignee": "", "renews": "DOT training every 3 years", "notes": "", "template": "", "files": []}, {"code": "PR-03", "cat": "product", "order": 2, "title": "Product spec sheets & line sheets", "why": "Current specs per product and the downloadable line sheets for each division.", "priority": "As needed", "division": "All divisions", "status": "On file", "assignee": "", "renews": "Update with pricing changes", "notes": "", "template": "", "files": []}, {"code": "PR-04", "cat": "product", "order": 3, "title": "Authorized distributor & authenticity letters", "why": "Letters from brands or distributors showing products are genuine. Buyers of phones and electronics often ask for them.", "priority": "As needed", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "", "notes": "", "template": "", "files": []}, {"code": "PR-05", "cat": "product", "order": 4, "title": "IMEI / blacklist check records", "why": "Proof each used or refurbished phone was checked as not lost, stolen or financed before sale.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Per shipment", "notes": "", "template": "", "files": []}, {"code": "PR-06", "cat": "product", "order": 5, "title": "Secondhand dealer requirements", "why": "Some states and cities license dealers in used electronics. Check Arizona and Florida rules before trading used phones.", "priority": "As needed", "division": "Phones & electronics", "status": "Not checked", "assignee": "Attorney", "renews": "", "notes": "", "template": "", "files": []}, {"code": "EX-01", "cat": "export", "order": 0, "title": "Commercial invoice & packing list templates", "why": "Required for every international shipment: buyer, consignee, HS codes, values, country of origin and package details.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "", "notes": "", "template": "", "files": []}, {"code": "EX-02", "cat": "export", "order": 1, "title": "Export filings (EEI / AES) & ITN records", "why": "Most exports over $2,500 per Schedule B line need an Electronic Export Information filing. If the forwarder files it, keep the ITN for each shipment.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Per shipment", "notes": "", "template": "", "files": []}, {"code": "EX-03", "cat": "export", "order": 2, "title": "Export classification & restricted-party screening", "why": "A note of each product's export classification, plus a saved check of every foreign buyer against the US Consolidated Screening List.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Screen every new buyer", "notes": "", "template": "", "files": []}, {"code": "EX-04", "cat": "export", "order": 3, "title": "Certificates of origin", "why": "Some Latin American buyers need one to clear customs or get reduced duties under a trade agreement.", "priority": "As needed", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Per shipment", "notes": "", "template": "", "files": []}, {"code": "EX-05", "cat": "export", "order": 4, "title": "Freight forwarder agreement & power of attorney", "why": "Signed terms with the Miami forwarder and the POA that lets them file export paperwork on SNP's behalf.", "priority": "As needed", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Per forwarder", "notes": "", "template": "", "files": []}, {"code": "SH-01", "cat": "shipping", "order": 0, "title": "Bills of lading & proof of delivery", "why": "Signed BOLs and delivery receipts for every shipment. They decide who carries the loss on a shortage or damage claim.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Per shipment", "notes": "", "template": "", "files": []}, {"code": "SH-02", "cat": "shipping", "order": 1, "title": "Freight carrier / broker agreements", "why": "Terms with any carrier or freight broker SNP books directly, with their certificate of insurance.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Per contract term", "notes": "", "template": "", "files": []}, {"code": "SH-03", "cat": "shipping", "order": 2, "title": "Freight claims procedure", "why": "A one-page checklist: note damage on the BOL, take photos, file within the carrier's deadline, track the claim.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "", "notes": "", "template": "", "files": []}, {"code": "FI-01", "cat": "finance", "order": 0, "title": "Bank resolution & authorized signers", "why": "The bank's resolution naming who can sign and move money on SNP's accounts. Record names only, not account numbers.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Update when signers change", "notes": "", "template": "", "files": []}, {"code": "FI-02", "cat": "finance", "order": 1, "title": "Monthly books & bank reconciliations", "why": "Monthly close from the accountant: reconciled bank statements, P&L and balance sheet.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Monthly", "notes": "", "template": "", "files": []}, {"code": "FI-03", "cat": "finance", "order": 2, "title": "Owner distribution records", "why": "Each distribution to the members and to the profit-share partner, with date, amount basis and approval.", "priority": "Important", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Per distribution", "notes": "", "template": "", "files": []}, {"code": "FI-04", "cat": "finance", "order": 3, "title": "Payment processor / merchant agreement", "why": "Terms for any card or ACH processor used to collect customer payments.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Per contract term", "notes": "", "template": "", "files": []}, {"code": "IN-01", "cat": "insurance", "order": 0, "title": "General liability policy", "why": "Covers injury and property damage claims. Many suppliers and large customers require a certificate before doing business.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Annual renewal", "notes": "", "template": "", "files": []}, {"code": "IN-02", "cat": "insurance", "order": 1, "title": "Product liability coverage", "why": "Covers claims that a product SNP sold caused harm. Matters most for chemicals and lithium-battery electronics.", "priority": "Critical", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Annual renewal", "notes": "", "template": "", "files": []}, {"code": "IN-03", "cat": "insurance", "order": 2, "title": "Cargo / transit insurance", "why": "Covers goods SNP owns while in transit, beyond the carrier's limited liability. Most relevant for phone exports.", "priority": "Important", "division": "Phones & electronics", "status": "Not checked", "assignee": "", "renews": "Annual renewal", "notes": "", "template": "", "files": []}, {"code": "WB-01", "cat": "web", "order": 0, "title": "Website Privacy Policy", "why": "Required because the site collects contact and account-application details.", "priority": "Important", "division": "All divisions", "status": "Needs review", "assignee": "Attorney", "renews": "Review yearly", "notes": "", "template": "", "files": []}, {"code": "WB-02", "cat": "web", "order": 1, "title": "Website Terms & Conditions", "why": "Rules for using the website and its forms.", "priority": "Important", "division": "All divisions", "status": "Needs review", "assignee": "Attorney", "renews": "Review yearly", "notes": "", "template": "", "files": []}, {"code": "WB-03", "cat": "web", "order": 2, "title": "Domain & hosting records", "why": "Registrar, hosting account owner and renewal date for snpwholesale.com.", "priority": "Important", "division": "All divisions", "status": "On file", "assignee": "Owner 1", "renews": "Annual domain renewal", "notes": "", "template": "", "files": []}, {"code": "RC-01", "cat": "records", "order": 0, "title": "Document retention policy", "why": "How long SNP keeps each kind of record. Tax and sales tax records are usually kept at least 4 to 7 years.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "Accountant", "renews": "Review yearly", "notes": "", "template": "", "files": []}, {"code": "RC-02", "cat": "records", "order": 1, "title": "Logo & brand files", "why": "Master logo files and colors, so everyone uses the same version.", "priority": "As needed", "division": "All divisions", "status": "On file", "assignee": "Owner 1", "renews": "", "notes": "", "template": "", "files": []}, {"code": "RC-03", "cat": "records", "order": 2, "title": "Key contacts sheet", "why": "Accountant, attorney, statutory agent, bank contact, the purchasing program account rep and main suppliers.", "priority": "As needed", "division": "All divisions", "status": "Not checked", "assignee": "", "renews": "Update as contacts change", "notes": "", "template": "", "files": []}];
window.SNP_STAGING_TEMPLATES = [{"key": "t1", "name": "Sourcing & Purchasing Services Agreement", "body": "# Sourcing & Purchasing Services Agreement\n\nStarter draft for SNP Wholesale LLC. Fill in the bracketed items and have an Arizona attorney review it before use.\n\nThis Sourcing & Purchasing Services Agreement (the \"Agreement\") is made on [DATE] between SNP Wholesale LLC, an Arizona limited liability company (\"SNP\"), and [CUSTOMER LEGAL NAME], a [STATE] [ENTITY TYPE] with its principal office at [ADDRESS] (\"Customer\").\n\n## 1. Services\n1.1 SNP will help Customer source bulk products, initially motor oil and related lubricants (the \"Products\"), by identifying sources, placing or coordinating orders through purchasing accounts and programs available to SNP, and coordinating delivery (the \"Services\").\n1.2 SNP acts as Customer's purchasing facilitator. SNP is not the manufacturer, seller or carrier of the Products and does not take title to them.\n\n## 2. Orders\n2.1 Customer will request Products in writing (email is enough), stating product, quantity, delivery address and requested delivery date.\n2.2 SNP will confirm each order in writing with the price, quantity and expected delivery window (an \"Order Confirmation\"). An order is binding only once both parties have confirmed it in writing.\n2.3 Prices are set by the supplier at the time of order. SNP will pass on the price shown in the Order Confirmation and will tell Customer before placing the order if it changes.\n\n## 3. Payment\n3.1 Customer pays the supplier directly for each order, in full, at the time the order is placed, using the payment method the supplier accepts.\n3.2 SNP does not extend credit, hold Customer funds or pay suppliers on Customer's behalf unless both parties agree in a separate signed writing.\n3.3 Customer is responsible for all sales, use and similar taxes on its purchases. Where Customer claims an exemption, it will give SNP and the supplier a valid, current exemption or resale certificate before the order.\n\n## 4. Title, risk and delivery\n4.1 Title and risk of loss pass from the supplier or carrier to Customer under the supplier's terms. SNP never holds title or risk of loss.\n4.2 Customer will inspect each delivery on arrival, note any shortage or visible damage on the delivery receipt, and tell SNP in writing within forty-eight (48) hours. SNP will help Customer present the claim to the supplier or carrier.\n\n## 5. Program benefits and fees\n5.1 Customer acknowledges that SNP may receive fees, rebates, cash-back or other rewards from suppliers or purchasing programs in connection with Customer's orders (\"Program Benefits\").\n5.2 Program Benefits belong to SNP. Customer has no claim to them and they do not reduce the price Customer pays.\n5.3 [OPTIONAL: Customer will pay SNP a service fee of [AMOUNT / %] per order, invoiced at [TIMING].]\n\n## 6. Warranties\n6.1 The only warranties for the Products are those given by the manufacturer or supplier. SNP will pass on any supplier warranty information it receives.\n6.2 SNP MAKES NO WARRANTY OF ITS OWN, EXPRESS OR IMPLIED, INCLUDING ANY WARRANTY OF MERCHANTABILITY OR FITNESS FOR A PARTICULAR PURPOSE.\n\n## 7. Non-circumvention and confidentiality\n7.1 During this Agreement and for twenty-four (24) months after it ends, Customer will not, directly or through others, contact or do business with any supplier, program or source introduced or disclosed by SNP in order to avoid SNP's involvement or Program Benefits.\n7.2 Each party will keep the other's pricing, sources, account details and customer information confidential and use it only to perform this Agreement.\n\n## 8. Limitation of liability\n8.1 Neither party is liable for indirect, incidental, consequential or lost-profit damages.\n8.2 SNP's total liability under this Agreement will not exceed the fees, if any, Customer paid SNP in the three (3) months before the claim.\n\n## 9. Indemnity\nCustomer will defend and indemnify SNP against claims arising from Customer's storage, handling, use or resale of the Products, or Customer's breach of this Agreement.\n\n## 10. Term and termination\n10.1 This Agreement starts on the date above and continues until either party ends it with thirty (30) days' written notice.\n10.2 Sections 3.3, 5, 6, 7, 8, 9 and 11 survive termination. Orders confirmed before termination will be completed.\n\n## 11. General\n11.1 Arizona law governs this Agreement. The parties consent to the state and federal courts in Maricopa County, Arizona.\n11.2 This is the entire agreement on its subject. Changes must be in a writing signed by both parties.\n11.3 Notices go to the addresses above (or by email to the address each party names below).\n11.4 Neither party may assign this Agreement without the other's written consent, except SNP may assign it to a successor business.\n\n## Signatures\n\nSNP WHOLESALE LLC\nBy: ______________________________\nName: [NAME]    Title: Member\nDate: ____________    Email: sales@snpwholesale.com\n\n[CUSTOMER LEGAL NAME]\nBy: ______________________________\nName: [NAME]    Title: [TITLE]\nDate: ____________    Email: [EMAIL]\n", "version": "Starter draft"}, {"key": "t2", "name": "Wholesale Terms & Conditions of Sale", "body": "# Wholesale Terms & Conditions of Sale\n\nStarter draft for SNP Wholesale LLC. Fill in the bracketed items and have an Arizona attorney review it before use.\n\nThese Terms & Conditions of Sale (\"Terms\") apply to every quote, order confirmation and invoice issued by SNP Wholesale LLC (\"SNP\") for products SNP sells, including phones, electronics and commercial supply products (the \"Products\"), to the buyer named on the order (\"Buyer\").\n\n## 1. Acceptance\n1.1 These Terms apply to every sale. Buyer accepts them by placing an order, paying a pro forma or accepting delivery.\n1.2 Different or additional terms in Buyer's purchase order or other documents do not apply unless SNP agrees to them in a signed writing.\n\n## 2. Quotes and orders\n2.1 Quotes are valid for [3] business days unless the quote says otherwise, and are subject to availability.\n2.2 An order is accepted only when SNP issues a written order confirmation or ships the Products.\n\n## 3. Prices and payment\n3.1 Prices are in US dollars and exclude taxes, duties, freight and insurance unless the quote says otherwise.\n3.2 Unless SNP has approved Buyer for credit in writing, payment is due in full by wire transfer or other method SNP accepts before shipment.\n3.3 Approved credit customers pay within [Net 15 / Net 30] days of invoice. Overdue amounts accrue interest at 1.5% per month or the highest lawful rate, if lower. Buyer pays reasonable costs of collection, including attorney fees.\n3.4 SNP may hold shipments while any amount is overdue.\n\n## 4. Taxes and resale certificates\nBuyer pays all sales, use, excise and similar taxes, and all import duties. To buy tax-exempt, Buyer must give SNP a valid resale or exemption certificate before the order ships. Buyer is responsible for any tax, interest or penalty if its certificate is invalid.\n\n## 5. Delivery, title and risk\n5.1 Domestic orders ship FOB shipping point unless the order confirmation says otherwise. International orders ship [EXW / FCA Miami, FL] (Incoterms 2020) unless the order confirmation says otherwise.\n5.2 Risk of loss passes to Buyer when the Products are handed to the first carrier. Title passes when SNP receives full payment.\n5.3 Delivery dates are estimates. SNP is not liable for delay.\n\n## 6. Inspection and claims\n6.1 Buyer will note any visible damage or shortage on the delivery receipt and report it to SNP in writing within forty-eight (48) hours of delivery, with photos.\n6.2 Buyer will report any other nonconformity within five (5) business days of delivery. Products not reported within these periods are accepted.\n\n## 7. Product condition and warranty\n7.1 New Products carry only the manufacturer's warranty, which SNP passes through to Buyer where it can.\n7.2 Refurbished or used Products are sold in the condition grade stated on the order confirmation, as defined in SNP's Product Condition & Grading Definitions. They are covered only by a [30]-day dead-on-arrival warranty, under which SNP will repair, replace or credit the unit at its option.\n7.3 EXCEPT AS STATED IN THIS SECTION, PRODUCTS ARE SOLD \"AS IS\" AND SNP DISCLAIMS ALL OTHER WARRANTIES, EXPRESS OR IMPLIED, INCLUDING MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.\n\n## 8. Returns\n8.1 Returns require a Return Merchandise Authorization (RMA) number from SNP, requested within the claim periods in Section 6.\n8.2 Returned Products must be in the condition shipped, with original packaging and accessories. Approved returns that are not SNP's error carry a [15]% restocking fee. Buyer pays return freight unless the return is SNP's error.\n\n## 9. Hazardous and regulated products\nBuyer will store, handle, transport and use chemical and battery-powered Products in line with the Safety Data Sheet and all applicable laws, and will not resell them to anyone not lawfully permitted to buy them.\n\n## 10. Export compliance\nBuyer will comply with all US export control and sanctions laws. Buyer will not sell, export or re-export Products to any prohibited country, person or end use, and confirms it is not on any US restricted-party list.\n\n## 11. Limitation of liability\nSNP IS NOT LIABLE FOR INDIRECT, INCIDENTAL, CONSEQUENTIAL OR LOST-PROFIT DAMAGES. SNP'S TOTAL LIABILITY FOR ANY ORDER WILL NOT EXCEED THE PRICE BUYER PAID FOR THE PRODUCTS IN THAT ORDER.\n\n## 12. Force majeure\nSNP is not liable for delays or failures caused by events beyond its reasonable control, including supplier shortages, carrier delays, customs holds, natural disasters and government action.\n\n## 13. General\n13.1 Arizona law governs these Terms, without regard to conflict-of-law rules. The UN Convention on Contracts for the International Sale of Goods does not apply. The parties consent to the state and federal courts in Maricopa County, Arizona.\n13.2 These Terms and the order confirmation are the entire agreement for each sale.\n13.3 If any part of these Terms is unenforceable, the rest remains in effect.\n\nSNP Wholesale LLC \u00b7 Arizona, USA \u00b7 sales@snpwholesale.com \u00b7 +1 (775) 250-6263\nVersion [1.0] \u00b7 Effective [DATE]\n", "version": "Starter draft"}, {"key": "t3", "name": "Mutual NDA & Non-Circumvention", "body": "# Mutual Non-Disclosure & Non-Circumvention Agreement\n\nStarter draft for SNP Wholesale LLC. Fill in the bracketed items and have an Arizona attorney review it before use.\n\nThis Mutual Non-Disclosure & Non-Circumvention Agreement (the \"Agreement\") is made on [DATE] between SNP Wholesale LLC, an Arizona limited liability company (\"SNP\"), and [COUNTERPARTY LEGAL NAME], a [STATE / COUNTRY] [ENTITY TYPE] (\"Counterparty\"). Each is a \"Party.\"\n\n## 1. Purpose\nThe Parties want to discuss and possibly carry out transactions involving [the purchase, sale or sourcing of products] (the \"Purpose\"). To do so they may share Confidential Information and introduce each other to suppliers, buyers and other contacts.\n\n## 2. Confidential Information\n2.1 \"Confidential Information\" means any non-public information a Party shares, in any form, including supplier and buyer identities and contact details, pricing, margins, volumes, purchasing programs, account arrangements, logistics and business plans.\n2.2 It does not include information that (a) is or becomes public through no fault of the receiving Party, (b) the receiving Party already knew without a duty of confidence, (c) the receiving Party lawfully receives from a third party without restriction, or (d) the receiving Party develops independently.\n\n## 3. Obligations\n3.1 The receiving Party will use Confidential Information only for the Purpose, will protect it with at least reasonable care, and will share it only with its employees and advisors who need it for the Purpose and are bound by similar duties.\n3.2 If the law or a court requires disclosure, the receiving Party will give prompt notice (where lawful) and disclose only what is required.\n3.3 On request, the receiving Party will return or destroy the other Party's Confidential Information.\n\n## 4. Non-circumvention\n4.1 \"Protected Contact\" means any supplier, buyer, program, financing source or other contact that one Party introduces or identifies to the other in connection with the Purpose, as shown by email or other written record.\n4.2 For twenty-four (24) months after the date of this Agreement, or after the last introduction if later, a Party will not, directly or indirectly, contact, solicit or do business with a Protected Contact introduced by the other Party in a way that bypasses the introducing Party or avoids the compensation that Party would otherwise earn, without that Party's prior written consent.\n4.3 If a Party breaches Section 4.2, it will pay the introducing Party the compensation that Party would have earned on the transaction, in addition to any other remedy.\n\n## 5. No obligation\nNeither Party has to enter into any transaction. Any transaction will be governed by a separate written agreement.\n\n## 6. Remedies\nA breach may cause harm that money alone cannot fix, so the non-breaching Party may seek an injunction in addition to any other remedy, without posting a bond where the law allows.\n\n## 7. Term\nThis Agreement lasts two (2) years from the date above. Confidentiality duties for information shared during the term continue for three (3) years after it ends.\n\n## 8. General\n8.1 Arizona law governs this Agreement. The Parties consent to the state and federal courts in Maricopa County, Arizona.\n8.2 This is the entire agreement on its subject. Changes must be in a writing signed by both Parties.\n8.3 Electronic signatures and counterparts are valid.\n\n## Signatures\n\nSNP WHOLESALE LLC\nBy: ______________________________\nName: [NAME]    Title: Member    Date: ____________\n\n[COUNTERPARTY LEGAL NAME]\nBy: ______________________________\nName: [NAME]    Title: [TITLE]    Date: ____________\n", "version": "Starter draft"}, {"key": "t4", "name": "Referral & Profit-Share Agreement", "body": "# Referral & Profit-Share Agreement\n\nStarter draft for SNP Wholesale LLC. Fill in the bracketed items and have an Arizona attorney review it before use. Settle with the accountant whether program costs are deducted before or after the split (Section 3.2).\n\nThis Referral & Profit-Share Agreement (the \"Agreement\") is made on [DATE] between SNP Wholesale LLC, an Arizona limited liability company (\"SNP\"), and [PARTNER LEGAL NAME], [a / an] [ENTITY TYPE OR INDIVIDUAL] (\"Partner\").\n\n## 1. Background\nPartner introduced SNP to [describe the sourcing arrangement, supplier relationships and customers] (the \"Program\"). Under the Program, customers buy products through purchasing accounts held by SNP, and SNP earns rewards, rebates or fees (\"Program Revenue\"). The Parties want to set out how Program Revenue is shared.\n\n## 2. Partner's role\n2.1 Partner will refer customers to SNP, help maintain the Program relationships it introduced, and give SNP the information it needs to place and track orders.\n2.2 Partner will follow all program terms SNP shares with it and will not make commitments on SNP's behalf.\n\n## 3. Profit share\n3.1 SNP will pay Partner [PARTNER %] of Net Program Revenue. SNP keeps [SNP %].\n3.2 \"Net Program Revenue\" means Program Revenue SNP actually receives in cleared funds, less [membership fees, renewal fees, bank and transfer fees, and other Program costs the Parties agree in writing]. [CONFIRM: costs deducted before the split / each Party bears its own costs.]\n3.3 No share is owed on Program Revenue that is reversed, clawed back or not received. If a reversal follows a payment, SNP may deduct it from the next payment.\n\n## 4. Statements and payment\n4.1 Within [15] days after the end of each month, SNP will give Partner a statement showing orders, Program Revenue received, deductions and Partner's share, and will pay that share by [ACH / wire].\n4.2 Partner may review SNP's records supporting the statements once per calendar year on [10] business days' notice. Questions about a statement must be raised within [90] days of receiving it.\n\n## 5. Taxes and status\n5.1 Partner is an independent contractor, not an employee, member or partner of SNP, and has no authority to bind SNP.\n5.2 Partner will give SNP a completed Form W-9 [or W-8 if foreign] before the first payment. SNP will issue tax forms as the law requires. Each Party pays its own taxes.\n\n## 6. Confidentiality and non-circumvention\n6.1 Each Party will keep the other's customers, suppliers, pricing, account arrangements and statements confidential.\n6.2 During this Agreement and for [24] months after it ends, neither Party will use the other's Protected Contacts (as defined in the Parties' NDA) to bypass the other or avoid the payments in this Agreement.\n\n## 7. Term and termination\n7.1 This Agreement runs for [one (1) year] from the date above and renews automatically for one-year terms unless either Party gives [60] days' written notice before renewal.\n7.2 Either Party may end it immediately on written notice if the other materially breaches it and does not cure within [15] days of notice.\n7.3 After termination, Partner is paid its share on Program Revenue from orders placed before the termination date, as and when SNP receives it.\n\n## 8. General\n8.1 Arizona law governs this Agreement. The Parties consent to the state and federal courts in Maricopa County, Arizona.\n8.2 This is the entire agreement on its subject and replaces any earlier understanding, written or oral. Changes must be in a writing signed by both Parties.\n8.3 Neither Party may assign this Agreement without the other's written consent.\n\n## Signatures\n\nSNP WHOLESALE LLC\nBy: ______________________________\nName: [NAME]    Title: Member    Date: ____________\n\nBy: ______________________________\nName: [NAME]    Title: Member    Date: ____________\n\n[PARTNER LEGAL NAME]\nBy: ______________________________\nName: [NAME]    Title: [TITLE]    Date: ____________\n", "version": "Starter draft"}, {"key": "t5", "name": "Customer Account & Credit Application", "body": "# Customer Account & Credit Application\n\nStarter form for SNP Wholesale LLC. Have an Arizona attorney review the guaranty section before use.\n\nSNP Wholesale LLC \u00b7 Arizona, USA \u00b7 sales@snpwholesale.com \u00b7 +1 (775) 250-6263\n\n## Section A: Business information\nLegal business name: ______________________________\nDBA (if any): ______________________________\nEntity type:  [ ] LLC   [ ] Corporation   [ ] Partnership   [ ] Sole proprietor   [ ] Other: ________\nState / country of formation: ____________    Year established: ________\nFederal EIN (or foreign tax ID): ______________________________\nBusiness address: ______________________________\nShipping address (if different): ______________________________\nWebsite: ______________________________\nMain contact: ______________________    Title: ______________\nPhone / WhatsApp: ______________________    Email: ______________________\nAccounts payable contact and email: ______________________________\n\n## Section B: Ownership\nOwner / officer name, title and % owned:\n1. ______________________________\n2. ______________________________\n\n## Section C: Products and volume\nDivisions of interest:  [ ] Oil   [ ] Phones & electronics   [ ] Commercial supply\nExpected monthly purchase volume (USD): ______________\nHow you will use the products:  [ ] Resale   [ ] Own use   [ ] Export\n\n## Section D: Sales tax\n[ ] We are buying for resale. Our resale / exemption certificate is attached. States: ______________\n[ ] We are not exempt. Charge sales tax where it applies.\n\n## Section E: Credit request (skip if paying in advance)\nCredit limit requested (USD): ______________    Terms requested:  [ ] Net 15   [ ] Net 30\nBank name and branch: ______________________    Bank contact and phone: ______________\nTrade references (company, contact, phone, email):\n1. ______________________________\n2. ______________________________\n3. ______________________________\n\n## Section F: Agreement and authorization\nBy signing, the Applicant confirms the information above is true and complete, agrees that all purchases are governed by SNP Wholesale LLC's Terms & Conditions of Sale (or, for sourcing services, the Sourcing & Purchasing Services Agreement) as updated from time to time, agrees to pay all invoices when due, and authorizes SNP to contact the bank and trade references listed and obtain business credit reports to evaluate this application.\n\nAuthorized signature: ______________________________\nPrinted name: ______________________    Title: ______________    Date: ____________\n\n## Section G: Personal guaranty (required for credit terms only)\nIn consideration of SNP Wholesale LLC extending credit to the Applicant, the undersigned personally and unconditionally guarantees prompt payment of all amounts the Applicant owes SNP now or later, including interest and collection costs and reasonable attorney fees. This guaranty is continuing until the guarantor revokes it in writing, which does not affect amounts owed before SNP receives the revocation. SNP need not pursue the Applicant first. Arizona law governs this guaranty.\n\nGuarantor signature: ______________________________\nPrinted name: ______________________    Date: ____________\nHome address: ______________________________\n\n## For SNP use only\nApproved by: ______________    Date: ____________    Credit limit: ________    Terms: ________\nResale certificate received:  [ ] Yes   [ ] No    Expires: ____________\nRestricted-party screening done (export buyers):  [ ] Yes    Date: ____________\n", "version": "Starter draft"}, {"key": "t6", "name": "Purchase Order", "body": "# Purchase Order\n\nSNP Wholesale LLC \u00b7 Arizona, USA \u00b7 sales@snpwholesale.com \u00b7 +1 (775) 250-6263\n\nPO number: SNP-PO-[YYYY]-[####]    PO date: ____________\nDivision:  [ ] Phones & electronics   [ ] Commercial supply   [ ] Oil\n\n## Vendor\nCompany: ______________________________\nContact: ______________________    Email / phone: ______________________\nVendor quote reference: ______________\n\n## Ship to\nName / company: ______________________________\nAddress: ______________________________\nReceiving contact and phone: ______________________________\nRequested ship date: ____________    Required delivery date: ____________\nShipping terms: [FOB origin / FOB destination / EXW / FCA]    Carrier or account #: ______________\n\n## Line items\nLine | Item / SKU | Description | Condition grade | Qty | Unit price (USD) | Total (USD)\n1 | __________ | __________________ | ________ | ____ | ________ | ________\n2 | __________ | __________________ | ________ | ____ | ________ | ________\n3 | __________ | __________________ | ________ | ____ | ________ | ________\n4 | __________ | __________________ | ________ | ____ | ________ | ________\n\nSubtotal: ________    Freight: ________    Tax: [Exempt \u2013 resale certificate on file / Amount]    Total: ________\n\nPayment terms: [Prepaid wire / Net __ / Other]\n\n## Purchase terms\n1. Please confirm this PO in writing within two (2) business days, including the ship date. SNP may cancel any line not confirmed.\n2. Ship only the quantities, items and condition grades shown. Substitutions require SNP's written approval.\n3. Include the PO number on every invoice, packing list and bill of lading.\n4. For chemicals, include current Safety Data Sheets and ship in compliance with DOT hazardous materials rules. For lithium-battery products, label and pack according to DOT and IATA rules.\n5. Used or refurbished electronics must be IMEI/blacklist clean and graded as stated. Units that fail inspection within [10] business days of receipt will be returned at the vendor's cost for credit or replacement.\n6. Vendor warrants it has good title to the goods, that they are genuine and not counterfeit, and that they comply with applicable law.\n7. This purchase is for resale. SNP's resale certificate is on file with the vendor [or attached].\n\n## Approval\nApproved by (SNP): ______________________    Date: ____________\nVendor acceptance: ______________________    Date: ____________\n", "version": "Starter draft"}];
